            Choice(id="ch13_c2", text="检视雷斯垂德的苏格兰场拘捕令，在格林盆泥潭边缘卡死伏击据点。", target_node_id="ch14_part1_fog_ambush"),
            Choice(id="ch13_c3", text="【视角切换：杰克·斯台普吞】窥探斯台普吞在梅利琵宅邸筹备致命晚餐的险恶心机。", target_node_id="stapleton_ch13_fatal_dinner", pov_switch=POV.STAPLETON),
