            Choice(id="h_ch12_p1_c2", text="【视角切换：杰克·斯台普吞】从斯台普吞视角体会他手持旧靴放出恶犬噬人的癫狂杀意。", target_node_id="stapleton_ch12_part1_screams_on_crags", pov_switch=POV.STAPLETON),
