            Choice(id="s_ch9_p1_c2", text="【视角切换：约翰·H·华生】切换至荒原乱石堆，体验华生与爵士端枪疾驰围捕狂暴越狱犯。", target_node_id="ch09_part2_moor_chase", pov_switch=POV.WATSON),
