            Choice(id="s_ch14_p1_c2", text="【视角切换：歇洛克·福尔摩斯】切换至决战前线，看神探连射五枪粉碎两百年魔咒。", target_node_id="holmes_ch14_part1_fog_ambush", pov_switch=POV.HOLMES),
